return ['domain'=>'acfml','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','language'=>'ar','project-id-version'=>'Advanced Custom Fields Multilingual 5.2.0','pot-creation-date'=>'2026-10-20 11:34+0000','po-revision-date'=>'2026-10-20 11:34+0000','x-generator'=>'PTC (Private Translation Cloud)','messages'=>['Advanced Custom Fields Multilingual'=>'Advanced Custom Fields Multilingual','https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/acfml/','Adds compatibility between WPML and Advanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">Documentation</a>'=>'يضيف التوافق بين WPML وAdvanced Custom Fields | <a href="https://wpml.org/documentation/translating-your-contents/acf/?utm_source=plugin&utm_medium=gui&utm_campaign=acfml">التوثيق</a>','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com/'=>'http://www.onthegosystems.com/','Displayed when editing an ACF field in a translation, showing its value in the original language; %1$s and %2$s turn the string into bold, and %3$s is the actual original value.%1$sOriginal%2$s: %3$s'=>'%1$sالأصل%2$s: %3$s','This type of ACF field will always be set to "Copy once".'=>'سيتم دائمًا تعيين هذا النوع من حقول ACF على ”نسخ لمرة واحدة“.','ACF field name:'=>'اسم حقل ACF:','ACF field type:'=>'نوع حقل ACF:','Translation preferences'=>'تفضيلات الترجمة','What to do with field\'s value when post/page is going to be translated'=>'ما يجب فعله بقيمة الحقل عند ترجمة المقال/الصفحة','Translate (your current setting, no longer offered for this field type)'=>'ترجمة (إعدادك الحالي، لم يعد متاحًا لنوع الحقل هذا)','Kept because it is your current setting. This value is no longer offered for this field type.'=>'تم الاحتفاظ به لأنه إعدادك الحالي. هذه القيمة لم تعد متاحة لنوع الحقل هذا.','Not recommended for this field type.'=>'غير موصى به لنوع الحقل هذا.','Translated pages start without this content.'=>'تبدأ الصفحات المترجمة بدون هذا المحتوى.','Editable in other languages, and starts empty.'=>'قابل للتعديل في اللغات الأخرى، ويبدأ فارغًا.','Visitors in every language always see exactly what the original shows.'=>'يرى الزوار في كل لغة تمامًا ما يظهر في الأصل.','Shown locked in other languages, so it cannot be edited there.'=>'يظهر مقفلاً في اللغات الأخرى، لذا لا يمكن تعديله هناك.','Starts the same as the original, then each language goes its own way.'=>'يبدأ بنفس الأصل، ثم تستقل كل لغة بمسارها الخاص.','Editable in every language, and permanently yours to maintain by hand.'=>'قابل للتعديل في كل لغة، ومسؤوليتك صيانته يدويًا بشكل دائم.','Visitors see this in their own language.'=>'يرى الزوار هذا بلغتهم الخاصة.','Filled by the translation and edited in the translation editor.'=>'يتم ملؤه بواسطة الترجمة وتعديله في محرر الترجمة.','Edit the field to set the translation preference.'=>'قم بتعديل الحقل لتعيين تفضيل الترجمة.','ACFML is updating translation preferences for strings in Gutenberg Blocks. Keep using your site as usual. This notice will disappear when the process is done.'=>'يقوم ACFML بتحديث تفضيلات الترجمة للنصوص في مكونات Gutenberg. استمر في استخدام موقعك كالمعتاد. سيختفي هذا الإشعار عند انتهاء العملية.','ACFML is enabled but not effective. It requires WPML in order to work.'=>'تم تمكين ACFML ولكنه غير فعال. يتطلب وجود WPML لكي يعمل.','ACFML is enabled but not effective. It requires Advanced Custom Fields or ACF PRO in order to work.'=>'تم تمكين ACFML ولكنها غير فعالة. تتطلب وجود Advanced Custom Fields أو ACF PRO لكي تعمل.','Activate Advanced Custom Fields'=>'تفعيل Advanced Custom Fields','Install Advanced Custom Fields'=>'تثبيت Advanced Custom Fields','Field groups are set to "Translatable" in WPML settings, which prevents ACF fields from being translated.'=>'تم تعيين مجموعات الحقول على ”قابل للترجمة“ في إعدادات WPML، مما يمنع ترجمة حقول ACF.','This is almost never intended.'=>'هذا الأمر غير مقصود تقريبًا.','A configuration file (wpml-config.xml) controls this setting on this site, so it cannot be changed from here. Edit that file, or ask whoever maintains it to set the ACF field group post type to Not translatable.'=>'يتحكم ملف تكوين (wpml-config.xml) في هذا الإعداد على هذا الموقع، لذا لا يمكن تغييره من هنا. قم بتعديل ذلك الملف، أو اطلب من الشخص المسؤول عن صيانته تعيين نوع مقال مجموعة حقول ACF على ”غير قابل للترجمة“.','Field group copies already created in other languages stay on the site. Changing this setting does not delete them.'=>'نسخ مجموعات الحقول التي تم إنشاؤها بالفعل بلغات أخرى ستبقى في الموقع. تغيير هذا الإعداد لا يؤدي إلى حذفها.','Set field groups to Not translatable'=>'تعيين مجموعات الحقول على غير قابل للترجمة','Why this matters'=>'لماذا يهم هذا الأمر','If any field is set to "Translatable", WPML will re-translate the %d posts using this field group.'=>'إذا تم تعيين أي حقل على ”ترجمة“، فسيقوم WPML بإعادة ترجمة %d مقالاً تستخدم مجموعة الحقول هذه.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to 1 minute.'=>'بعض المقالات التي تستخدم مجموعة الحقول هذه لها ترجمات. بمجرد تغيير خيار الترجمة، سيحتاج WPML إلى تحديث حالة ترجمة المقالات. قد يستغرق هذا ما يصل إلى دقيقة واحدة.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d hours.'=>'بعض المقالات التي تستخدم مجموعة الحقول هذه لها ترجمات. بمجرد تغيير خيار الترجمة، سيحتاج WPML إلى تحديث حالة ترجمة المقالات. قد يستغرق هذا ما يصل إلى %d ساعة.','Some posts using this field group have translations. Once you change the translation option, WPML needs to update the translation status of the posts. This can take up to %d minutes.'=>'بعض المقالات التي تستخدم مجموعة الحقول هذه لها ترجمات. بمجرد تغيير خيار الترجمة، سيحتاج WPML إلى تحديث حالة ترجمة المقالات. قد يستغرق هذا ما يصل إلى %d دقيقة.','Locked by WPML so that ACF fields stay translatable. Click here to unlock and change it anyway.'=>'مقفل بواسطة WPML لكي تظل حقول ACF قابلة للترجمة. انقر هنا لإلغاء القفل وتغييره على أي حال.','Set translation preferences for the attached taxonomy'=>'تعيين تفضيلات الترجمة للتصنيف المرفق','Set translation preferences for the attached post type'=>'تعيين تفضيلات الترجمة لنوع المقال المرفق','If you want to translate your fields, go to the WPML Settings page and make the taxonomy attached to this field group translatable. '=>'إذا كنت ترغب في ترجمة حقولك، فانتقل إلى صفحة إعدادات WPML واجعل التصنيف المرفق بمجموعة الحقول هذه قابلاً للترجمة. ','If you want to translate your fields, go to the WPML Settings page and %1$smake the post type attached to this field group translatable%2$s.'=>'إذا كنت ترغب في ترجمة حقولك، فانتقل إلى صفحة إعدادات WPML و%1$sاجعل نوع المقال المرفق بمجموعة الحقول هذه قابلاً للترجمة%2$s.','Expert'=>'خبير','Same content in every language, translated'=>'نفس المحتوى في كل لغة، مترجم','Each language has its own content'=>'لكل لغة محتواها الخاص','Translate is not offered on container fields, because it replaces the value your theme reads. The fields inside carry their own preferences.'=>'خيار ”ترجمة“ غير متاح في حقول الحاويات، لأنه يستبدل القيمة التي يقرأها قالبك. الحقول الموجودة بالداخل تحمل تفضيلاتها الخاصة.','Translate lets each language point at its own address, which an external link often needs. A link to a page on this site already points at that page in the reader\'s language, so leave it as it is.'=>'يتيح خيار ”ترجمة“ لكل لغة الإشارة إلى عنوانها الخاص، وهو ما يحتاجه الرابط الخارجي غالبًا. أما الرابط الذي يشير إلى صفحة في هذا الموقع فهو يشير بالفعل إلى تلك الصفحة بلغة القارئ، لذا اتركه كما هو.','Translate sends the link text and the URL. The target keeps the value you set, and a URL you leave as it is points at the page in the reader\'s language.'=>'يرسل خيار ”ترجمة“ نص الرابط وعنوان URL. يحتفظ الهدف بالقيمة التي حددتها، ويظل عنوان URL الذي تتركه كما هو مشيرًا إلى الصفحة بلغة القارئ.','Translating an address produces one that does not exist. An e-mail address is the same in every language.'=>'تؤدي ترجمة العنوان إلى إنتاج عنوان غير موجود. عنوان البريد الإلكتروني هو نفسه في كل لغة.','A color code is not language content. Translating it changes the color your visitors see.'=>'رمز اللون ليس محتوى لغويًا. ترجمته تغير اللون الذي يراه زوارك.','The stored value is a fixed date format that your theme reads. Translating it breaks the format.'=>'القيمة المخزنة هي تنسيق تاريخ ثابت يقرأه قالبك. ترجمتها تؤدي إلى كسر التنسيق.','The stored value is the choice key, not the label your visitors see. Translating it stops the key from matching your choices. Translate the labels in <b>String Translation</b> instead.'=>'القيمة المخزنة هي مفتاح الاختيار، وليست التسمية التي يراها زوارك. ترجمتها تمنع المفتاح من مطابقة اختياراتك. ترجم التسميات في <b>ترجمة النصوص</b> بدلاً من ذلك.','This value is read by your theme or plugin code. A translated value can stop matching what the code expects.'=>'تتم قراءة هذه القيمة بواسطة كود القالب أو الإضافة الخاصة بك. القيمة المترجمة قد تتوقف عن مطابقة ما يتوقعه الكود.','The file decides this again on every import, so changes made elsewhere do not stick.'=>'يقرر الملف هذا مرة أخرى عند كل استيراد، لذا فإن التغييرات التي يتم إجراؤها في مكان آخر لا تثبت.','Edit %s, or remove the entry there, to manage this field on this screen.'=>'قم بتعديل %s، أو قم بإزالة الإدخال هناك، لإدارة هذا الحقل في هذه الشاشة.','Edit the configuration file, or remove the entry there, to manage this field on this screen.'=>'قم بتعديل ملف التكوين، أو قم بإزالة الإدخال هناك، لإدارة هذا الحقل في هذه الشاشة.','That is not the value selected above. Saving this field group applies the value above.'=>'هذه ليست القيمة المحددة أعلاه. حفظ مجموعة الحقول هذه يطبق القيمة أعلاه.','This field group is also in %s. That file re-applies these settings the next time the group is synced.'=>'مجموعة الحقول هذه موجودة أيضًا في %s. يعيد ذلك الملف تطبيق هذه الإعدادات في المرة القادمة التي تتم فيها مزامنة المجموعة.','Locked. Managed by your theme, in its wpml-config.xml file.'=>'مقفل. تتم إدارته بواسطة قالبك، في ملف wpml-config.xml الخاص به.','Locked. Managed by a plugin, in its wpml-config.xml file.'=>'مقفل. تتم إدارته بواسطة إضافة، في ملف wpml-config.xml الخاص بها.','Locked. Managed by a configuration file WPML downloaded for one of your plugins or themes.'=>'مقفل. تتم إدارته بواسطة ملف تكوين قام WPML بتنزيله لإحدى إضافاتك أو قوالبك.','Locked. Managed by the custom XML configuration saved in WPML settings.'=>'مقفل. تتم إدارته بواسطة تكوين XML المخصص المحفوظ في إعدادات WPML.','Locked. Managed by a configuration file on this site.'=>'مقفل. تتم إدارته بواسطة ملف تكوين على هذا الموقع.','Set in the field group "%s", which uses the same field name.'=>'تم التعيين في مجموعة الحقول ”%s“، والتي تستخدم نفس اسم الحقل.','Set in the field group\'s local JSON file.'=>'تم التعيين في ملف JSON المحلي لمجموعة الحقول.','Set in the field group\'s local JSON file, %s.'=>'تم التعيين في ملف JSON المحلي لمجموعة الحقول، %s.','Registered with PHP by your theme or a plugin.'=>'مسجل بواسطة PHP من خلال قالبك أو إضافة.','Set on the WPML Settings screen (Custom Fields Translation).'=>'تم التعيين في شاشة إعدادات WPML (ترجمة الحقول المخصصة).','Set here, on this screen.'=>'تم التعيين هنا، في هذه الشاشة.','Right now this field is translated, so visitors see it in their own language.'=>'في الوقت الحالي، هذا الحقل مترجم، لذا يراه الزوار بلغتهم الخاصة.','Right now this field stays identical in every language.'=>'في الوقت الحالي، يظل هذا الحقل متطابقًا في كل لغة.','Right now this field starts as a copy in every language, then each language keeps its own.'=>'في الوقت الحالي، يبدأ هذا الحقل كنسخة في كل لغة، ثم تحتفظ كل لغة بنسختها الخاصة.','Right now this field stays out of translations.'=>'في الوقت الحالي، يظل هذا الحقل خارج الترجمات.','Don\'t translate'=>'عدم الترجمة','Copy'=>'نسخ','Copy once'=>'نسخ لمرة واحدة','Translate'=>'ترجمة','Field groups'=>'مجموعات الحقول','Fields'=>'الحقول','Posts'=>'المقالات','Review them one by one'=>'مراجعتها واحدة تلو الأخرى','Apply the recommended setup to %d group'=>'تطبيق الإعداد الموصى به على جميع الـ %d' . "\0" . 'تطبيق الإعداد الموصى به على كافة %d' . "\0" . 'تطبيق الإعداد الموصى به على كلتيهما %d' . "\0" . 'تطبيق الإعداد الموصى به على جميع الـ %d' . "\0" . 'تطبيق الإعداد الموصى به على جميع الـ %d' . "\0" . 'تطبيق الإعداد الموصى به على مجموعة %d واحدة','%d ACF field group is not configured for translation.'=>'لا توجد %d مجموعات حقول ACF مهيأة للترجمة.' . "\0" . 'لم يتم تهيئة %d مجموعة حقول ACF للترجمة.' . "\0" . 'مجموعتا حقول ACF اثنتان %d غير مهيأتين للترجمة.' . "\0" . '%d مجموعات حقول ACF غير مهيأة للترجمة.' . "\0" . '%d مجموعة حقول ACF غير مهيأة للترجمة.' . "\0" . 'هناك مجموعة حقول ACF %d واحدة غير مهيأة للترجمة.','%d post'=>'%d منشور' . "\0" . '%d مقال' . "\0" . 'منشوران اثنان %d' . "\0" . '%d منشورات' . "\0" . '%d منشورًا' . "\0" . 'مقال %d واحد','%1$s field, used on %2$s, would be skipped and stay in %3$s.'=>'سيتم تخطي %1$s حقول، مستخدمة في %2$s، وستظل باللغة %3$s.' . "\0" . 'سيتم تخطي حقل واحد %1$s، مستخدم في %2$s، وسيظل باللغة %3$s.' . "\0" . 'سيتم تخطي حقلين اثنين %1$s، مستخدمين في %2$s، وسيظلان باللغة %3$s.' . "\0" . 'سيتم تخطي %1$s حقول، مستخدمة في %2$s، وستظل باللغة %3$s.' . "\0" . 'سيتم تخطي %1$s حقلًا، مستخدمة في %2$s، وستظل باللغة %3$s.' . "\0" . 'سيتم تخطي %1$s حقل، مستخدمة في %2$s، وستظل باللغة %3$s.','%1$s field, used on %2$s, would be skipped and stay untranslated.'=>'سيتم تخطي %1$s حقول، مستخدمة في %2$s، وستظل بدون ترجمة.' . "\0" . 'سيتم تخطي حقل واحد %1$s، مستخدم في %2$s، وسيظل بدون ترجمة.' . "\0" . 'سيتم تخطي حقلين اثنين %1$s، مستخدمين في %2$s، وسيظلان بدون ترجمة.' . "\0" . 'سيتم تخطي %1$s حقول، مستخدمة في %2$s، وستظل بدون ترجمة.' . "\0" . 'سيتم تخطي %1$s حقلًا، مستخدمة في %2$s، وستظل بدون ترجمة.' . "\0" . 'سيتم تخطي %1$s حقل، مستخدمة في %2$s، وستظل بدون ترجمة.','You are not allowed to change the translation setup of ACF field groups.'=>'غير مسموح لك بتغيير إعداد ترجمة مجموعات حقول ACF.','You are not allowed to change the WPML translation settings on this site.'=>'غير مسموح لك بتغيير إعدادات ترجمة WPML على هذا الموقع.','To change the translation options for custom fields, edit the field group "%s".'=>'لتغيير خيارات الترجمة للحقول المخصصة، قم بتعديل مجموعة الحقول ”%s“.','These fields come from ACF’s Local JSON files. To change their translation options, go to ACF → Field Groups, sync them, and then edit their settings.'=>'تأتي هذه الحقول من ملفات JSON المحلية الخاصة بـ ACF. لتغيير خيارات ترجمتها، انتقل إلى ACF ← مجموعات الحقول، وقم بمزامنتها، ثم قم بتعديل إعداداتها.','This field and its translation setting are registered via PHP by your theme or plugin. Changes made here will override the original configuration.'=>'هذا الحقل وإعداد ترجمته مسجلان عبر PHP بواسطة قالبك أو إضافتك. التغييرات التي يتم إجراؤها هنا ستتجاوز التكوين الأصلي.','ACF translation setup'=>'إعداد ترجمة ACF','Translation setup'=>'إعداد الترجمة','You are not allowed to review the translation setup of ACF field groups.'=>'غير مسموح لك بمراجعة إعداد ترجمة مجموعات حقول ACF.','Field group'=>'مجموعة حقول','Setup'=>'إعداد','Actions'=>'الإجراءات','This site has no ACF field groups yet.'=>'لا يحتوي هذا الموقع على مجموعات حقول ACF بعد.','Alert:'=>'تنبيه:','How to do that'=>'كيفية القيام بذلك','View fields'=>'عرض الحقول','Open Dashboard'=>'فتح لوحة التحكم','Apply the recommended setup'=>'تطبيق الإعداد الموصى به','Every field group stored in this site’s database already has a translation setup.'=>'كل مجموعة حقول مخزنة في قاعدة بيانات هذا الموقع لديها بالفعل إعداد ترجمة.','Back to the field groups'=>'العودة إلى مجموعات الحقول','Every field in those groups then gets the translation preference WPML recommends for its field type. A preference that was set by hand in one of them is replaced.'=>'تحصل كل الحقول في تلك المجموعات بعد ذلك على تفضيل الترجمة الذي يوصي به WPML لنوع الحقل الخاص بها. سيتم استبدال أي تفضيل تم تعيينه يدويًا في إحداها.','Field groups that come from your theme, a plugin’s code, or an acf-json file are not changed. They cannot be saved from here.'=>'مجموعات الحقول التي تأتي من قالبك، أو كود إضافة، أو ملف acf-json لا تتغير. لا يمكن حفظها من هنا.','Cancel'=>'إلغاء','%d field group.'=>'%d مجموعات حقول.' . "\0" . '%d مجموعة حقول.' . "\0" . 'مجموعتا حقول اثنتان %d.' . "\0" . '%d مجموعات حقول.' . "\0" . '%d مجموعة حقول.' . "\0" . 'مجموعة حقول %d واحدة.','All of them have a translation setup.'=>'جميعها لديها إعداد ترجمة.','%d is not configured.'=>'%d غير مهيأة.' . "\0" . '%d غير مهيأة.' . "\0" . 'اثنتان %d غير مهيأتين.' . "\0" . '%d غير مهيأة.' . "\0" . '%d غير مهيأة.' . "\0" . 'هناك %d واحدة غير مهيأة.','Apply recommended setup to the %d unconfigured group'=>'تطبيق الإعداد الموصى به على كافة المجموعات الـ %d غير المهيأة' . "\0" . 'تطبيق الإعداد الموصى به على كافة الـ %d مجموعة غير مهيأة' . "\0" . 'تطبيق الإعداد الموصى به على كلتا المجموعتين الـ %d غير المهيأتين' . "\0" . 'تطبيق الإعداد الموصى به على كافة المجموعات الـ %d غير المهيأة' . "\0" . 'تطبيق الإعداد الموصى به على كافة المجموعات الـ %d غير المهيأة' . "\0" . 'تطبيق الإعداد الموصى به على مجموعة %d واحدة غير مهيأة','This sets %1$d field group to “%2$s”.'=>'يؤدي هذا إلى تعيين %1$d مجموعات حقول على ”%2$s“.' . "\0" . 'يؤدي هذا إلى تعيين %1$d مجموعة حقول على ”%2$s“.' . "\0" . 'يؤدي هذا إلى تعيين مجموعتي حقول اثنتين %1$d على ”%2$s“.' . "\0" . 'يؤدي هذا إلى تعيين %1$d مجموعات حقول على ”%2$s“.' . "\0" . 'يؤدي هذا إلى تعيين %1$d مجموعة حقول على ”%2$s“.' . "\0" . 'يؤدي هذا إلى تعيين مجموعة حقول %1$d واحدة على ”%2$s“.','%d field group is defined in code, so it cannot be configured from here.'=>'تم تعريف %d مجموعات حقول في الكود، لذا لا يمكن تهيئتها من هنا.' . "\0" . 'تم تعريف %d مجموعة حقول في الكود، لذا لا يمكن تهيئتها من هنا.' . "\0" . 'تم تعريف مجموعتي حقول اثنتين %d في الكود، لذا لا يمكن تهيئتهما من هنا.' . "\0" . 'تم تعريف %d مجموعات حقول في الكود، لذا لا يمكن تهيئتها من هنا.' . "\0" . 'تم تعريف %d مجموعة حقول في الكود، لذا لا يمكن تهيئتها من هنا.' . "\0" . 'تم تعريف مجموعة حقول %d واحدة في الكود، لذا لا يمكن تهيئتها من هنا.','Not configured'=>'غير مهيأ','Not configured (defined in code)'=>'غير مهيأ (مُعرّف في الكود)','Set for each field (defined in code)'=>'محددة لكل حقل (مُعرفة في الكود)','Set for each field in WPML Settings (defined in code)'=>'معين لكل حقل في إعدادات WPML (معرّف في الكود)','%d field set manually'=>'تم تعيين %d حقول يدويًا' . "\0" . 'تم تعيين %d حقل يدويًا' . "\0" . 'تم تعيين حقلين اثنين %d يدويًا' . "\0" . 'تم تعيين %d حقول يدويًا' . "\0" . 'تم تعيين %d حقلًا يدويًا' . "\0" . 'تم تعيين حقل %d واحد يدويًا','Nothing decides how these fields are translated. Set %s on the fields in the code that registers this group.'=>'لا يوجد ما يحدد كيفية ترجمة هذه الحقول. قم بتعيين %s في الحقول الموجودة في الكود الذي يسجل هذه المجموعة.','from an acf-json file'=>'من ملف acf-json','from an acf-json file that is newer than this site’s copy'=>'من ملف acf-json أحدث من نسخة هذا الموقع','from your theme or a plugin’s code'=>'من قالبك أو كود إضافة','%d field group now uses the recommended setup.'=>'تستخدم الآن %d مجموعات حقول الإعداد الموصى به.' . "\0" . 'تستخدم الآن %d مجموعة حقول الإعداد الموصى به.' . "\0" . 'تستخدم الآن مجموعتا حقول اثنتان %d الإعداد الموصى به.' . "\0" . 'تستخدم الآن %d مجموعات حقول الإعداد الموصى به.' . "\0" . 'تستخدم الآن %d مجموعة حقول الإعداد الموصى به.' . "\0" . 'تستخدم الآن مجموعة حقول %d واحدة الإعداد الموصى به.','%d field group has a newer acf-json file waiting to be synced, so that file decides its setup.'=>'تحتوي %d مجموعات حقول على ملف acf-json أحدث ينتظر المزامنة، لذا تحدد تلك الملفات إعدادها.' . "\0" . 'تمتلك %d مجموعة حقول ملف acf-json أحدث ينتظر المزامنة، لذا فإن تلك الملفات هي التي تحدد إعداداتها.' . "\0" . 'تحتوي مجموعتا حقول اثنتان %d على ملف acf-json أحدث ينتظر المزامنة، لذا تحدد تلك الملفات إعدادها.' . "\0" . 'تحتوي %d مجموعات حقول على ملف acf-json أحدث ينتظر المزامنة، لذا تحدد تلك الملفات إعدادها.' . "\0" . 'تحتوي %d مجموعة حقول على ملف acf-json أحدث ينتظر المزامنة، لذا تحدد تلك الملفات إعدادها.' . "\0" . 'تمتلك مجموعة حقول %d واحدة ملف acf-json أحدث ينتظر المزامنة، لذا فإن ذلك الملف هو الذي يحدد إعدادها.','Translation Option'=>'خيار الترجمة','Multilingual Setup'=>'إعداد متعدد اللغات','Loading...'=>'جاري التحميل...','Activate <b>String Translation</b>'=>'تفعيل <b>ترجمة النصوص</b>','To translate field group names and labels, please %1$sinstall and activate WPML’s String Translation add-on%2$s.'=>'لترجمة أسماء مجموعات الحقول وتسمياتها، يرجى %1$sتثبيت وتفعيل إضافة ترجمة النصوص من WPML%2$s.','Activate now'=>'تفعيل الآن','Go back'=>'العودة','Set Up <b>Field Group Translation</b>'=>'إعداد <b>ترجمة مجموعة الحقول</b>','To translate field labels from the <b>Translation Management</b> dashboard, finish the <b>Multilingual Setup</b> and save your field group settings.'=>'لترجمة تسميات الحقول من لوحة <b>إدارة الترجمة</b>، أكمل <b>إعداد متعدد اللغات</b> واحفظ إعدادات مجموعة الحقول.','OK'=>'موافق','Translate Field Labels'=>'ترجمة تسميات الحقول','To translate field labels, use the <b>Translation Management</b> dashboard.'=>'لترجمة تسميات الحقول، استخدم لوحة <b>إدارة الترجمة</b>.','Translate in <b>Translation Management</b>'=>'ترجمة في <b>إدارة الترجمة</b>','Don’t want to translate field labels? %1$sLearn how to disable field label translation%2$s'=>'ألا تريد ترجمة تسميات الحقول؟ %1$sتعرف على كيفية تعطيل ترجمة تسميات الحقول%2$s','Field Labels Partly Translated'=>'تسميات الحقول مترجمة جزئيًا','Some field labels in this group are still untranslated. To finish translating them, go to the <b>Translation Management</b> dashboard.'=>'لا تزال بعض تسميات الحقول في هذه المجموعة غير مترجمة. لإتمام ترجمتها، انتقل إلى لوحة <b>إدارة الترجمة</b>.','Fields Labels Already Translated'=>'تسميات الحقول مترجمة بالفعل','You already translated all field labels in this group. To update any translations, go to the <b>Translation Management</b> dashboard.'=>'لقد ترجمت جميع تسميات الحقول في هذه المجموعة. لتحديث أي ترجمات، انتقل إلى لوحة <b>إدارة الترجمة</b>.','Go to <b>Translation Management</b>'=>'انتقل إلى <b>إدارة الترجمة</b>','Select a translation option for this field group'=>'حدد خيار ترجمة لمجموعة الحقول هذه','Visitors everywhere see the same pages, in their own language. Text is translated; layout and settings stay identical.'=>'يرى الزوار في كل مكان نفس الصفحات بلغتهم الخاصة. يتم ترجمة النص؛ بينما يظل التخطيط والإعدادات متطابقة.','You translate in the WPML <b>Translation Editor</b>. This works with automatic translation and <b>Translate Everything</b>.'=>'تتم الترجمة في <b>محرر الترجمة</b> من WPML. يعمل هذا مع الترجمة التلقائية و<b>ترجم كل شيء</b>.','Every language’s pages are written and maintained on their own. Fields start as a copy of the original, then go their own way.'=>'تتم كتابة صفحات كل لغة وصيانتها بشكل مستقل. تبدأ الحقول كنسخة من الأصل، ثم تسلك مسارها الخاص.','You edit each language in the WordPress editor. WPML does not sync them afterwards, and automatic translation does not apply.'=>'أنت تقوم بتحرير كل لغة في محرر WordPress. لا يقوم WPML بمزامنتها بعد ذلك، ولا تنطبق الترجمة التلقائية.','If you are migrating a site, your existing field groups will use the Expert setup. This allows you to manually choose the translation option for each field in the group.'=>'إذا كنت تقوم بنقل موقع، فستستخدم مجموعات الحقول الحالية إعداد خبير. يتيح لك هذا اختيار خيار الترجمة يدويًا لكل حقل في المجموعة.','This option is %1$snot recommended%2$s for new field groups.'=>'هذا الخيار %1$sغير موصى به%2$s لمجموعات الحقول الجديدة.','Expert setup documentation'=>'وثائق إعداد خبير','Choose'=>'اختيار','recommended for this site'=>'موصى به لهذا الموقع','Change option'=>'تغيير الخيار','A Much Simpler Way to Translate Your ACF Sites'=>'طريقة أبسط بكثير لترجمة مواقع ACF الخاصة بك','This new release of ACFML allows you to configure multilingual sites in one-click, instead of many complex settings. Choose how to setup the translation for the fields.'=>'يسمح لك هذا الإصدار الجديد من ACFML بتكوين المواقع متعددة اللغات بنقرة واحدة، بدلاً من العديد من الإعدادات المعقدة. اختر كيفية إعداد الترجمة للحقول.','Go to WPML Settings'=>'انتقل إلى إعدادات WPML','Need help choosing?'=>'هل تحتاج إلى مساعدة في الاختيار؟','Documentation'=>'وثائق','How to translate field labels »'=>'كيفية ترجمة تسميات الحقول »','This setup translates field values.'=>'هذا الإعداد يترجم قيم الحقول.','Translate field labels and dropdown choice labels separately. Find them under ACF Field Group in the <b>Translation Dashboard</b>.'=>'ترجم تسميات الحقول وتسميات خيارات القوائم المنسدلة بشكل منفصل. يمكنك العثور عليها ضمن ACF Field Group في <b>لوحة إدارة الترجمة</b>.','Review these translation setting changes'=>'مراجعة تغييرات إعدادات الترجمة هذه','Saving this field group makes these changes:'=>'حفظ مجموعة الحقول هذه يؤدي إلى التغييرات التالية:','%1$s: from “%2$s” to “%3$s”'=>'%1$s: من ”%2$s“ إلى ”%3$s“','Switching to the field-by-field setup keeps every field\'s current setting. From here you set each field yourself.'=>'التبديل إلى إعداد حقل بحقل يحافظ على الإعداد الحالي لكل حقل. من هنا يمكنك تعيين كل حقل بنفسك.','New translations use the new settings automatically.'=>'تستخدم الترجمات الجديدة الإعدادات الجديدة تلقائيًا.','Not set'=>'لم يتم التعيين','No posts with translations use this field group yet, so nothing has to be sent again.'=>'لا توجد مقالات مترجمة تستخدم مجموعة الحقول هذه بعد، لذا لا يلزم إرسال أي شيء مرة أخرى.','No terms with translations use this field group yet, so nothing has to be sent again.'=>'لا توجد تصنيفات مترجمة تستخدم مجموعة الحقول هذه بعد، لذا لا يلزم إرسال أي شيء مرة أخرى.','No posts or terms with translations use this field group yet, so nothing has to be sent again.'=>'لا توجد مقالات أو تصنيفات مترجمة تستخدم مجموعة الحقول هذه بعد، لذا لا يلزم إرسال أي شيء مرة أخرى.','Only apply to new translations'=>'التطبيق على الترجمات الجديدة فقط','Checking how much content this affects...'=>'يتم التحقق من كمية المحتوى المتأثر بهذا...','Save changes'=>'حفظ التغييرات','No, go back'=>'لا، العودة','Updating them sends them for translation again, which may use translation words.'=>'تحديثها يؤدي لإرسالها للترجمة مرة أخرى، مما قد يستهلك كلمات ترجمة.','Updating them marks their translations as needing an update. WPML does not send them for translation. You can send them from the Translation Dashboard.'=>'يؤدي تحديثها إلى تمييز ترجماتها بأنها بحاجة إلى تحديث. لا يرسلها WPML للترجمة. يمكنك إرسالها من لوحة إدارة الترجمة.','Switching the setup applies the recommended value to the %d field in this group.'=>'يؤدي تبديل الإعداد إلى تطبيق القيمة الموصى بها على كافة الحقول الـ %d في هذه المجموعة.' . "\0" . 'يؤدي تبديل الإعداد إلى تطبيق القيمة الموصى بها على جميع الحقول الـ %d في هذه المجموعة.' . "\0" . 'يؤدي تبديل الإعداد إلى تطبيق القيمة الموصى بها على كلا الحقلين (%d) في هذه المجموعة.' . "\0" . 'يؤدي تبديل الإعداد إلى تطبيق القيمة الموصى بها على كافة الحقول الـ %d في هذه المجموعة.' . "\0" . 'يؤدي تبديل الإعداد إلى تطبيق القيمة الموصى بها على كافة الحقول الـ %d في هذه المجموعة.' . "\0" . 'يؤدي تبديل الإعداد إلى تطبيق القيمة الموصى بها على حقل %d واحد في هذه المجموعة.','%d post already has translations that used the old settings.'=>'تحتوي %d منشورات بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'يوجد %d مقالاً لديها ترجمات بالفعل استخدمت الإعدادات القديمة.' . "\0" . 'يحتوي منشوران (%d) بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'تحتوي %d منشورات بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'يحتوي %d منشورًا بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'يوجد مقال %d واحد لديه ترجمات بالفعل استخدمت الإعدادات القديمة.','%d term already has translations that used the old settings.'=>'تحتوي %d مصطلحات بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'يوجد %d تصنيفًا لديها ترجمات بالفعل استخدمت الإعدادات القديمة.' . "\0" . 'يحتوي مصطلحان (%d) بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'تحتوي %d مصطلحات بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'يحتوي %d مصطلحًا بالفعل على ترجمات استخدمت الإعدادات القديمة.' . "\0" . 'يوجد تصنيف %d واحد لديه ترجمات بالفعل استخدمت الإعدادات القديمة.','%d post uses this field group.'=>'تستخدم %d منشورات مجموعة الحقول هذه.' . "\0" . 'يستخدم %d مقالاً مجموعة الحقول هذه.' . "\0" . 'يستخدم منشوران اثنان %d مجموعة الحقول هذه.' . "\0" . 'تستخدم %d منشورات مجموعة الحقول هذه.' . "\0" . 'يستخدم %d منشورًا مجموعة الحقول هذه.' . "\0" . 'يستخدم مقال %d واحد مجموعة الحقول هذه.','%d post is translated by hand, so WPML does not send it for translation.'=>'تتم ترجمة %d منشورات يدويًا، لذا لا يرسلها WPML للترجمة.' . "\0" . 'تتم ترجمة منشور واحد %d يدويًا، لذا لا يرسله WPML للترجمة.' . "\0" . 'تتم ترجمة منشورين (%d) يدويًا، لذا لا يرسلهما WPML للترجمة.' . "\0" . 'تتم ترجمة %d منشورات يدويًا، لذا لا يرسلها WPML للترجمة.' . "\0" . 'تتم ترجمة %d منشورًا يدويًا، لذا لا يرسلها WPML للترجمة.' . "\0" . 'تتم ترجمة %d منشور يدويًا، لذا لا يرسلها WPML للترجمة.','Also update the %d existing post'=>'تحديث المنشورات الحالية الـ %d أيضًا' . "\0" . 'تحديث الـ %d مقالاً الحالية أيضًا' . "\0" . 'تحديث المنشورين الحاليين الـ %d أيضًا' . "\0" . 'تحديث المنشورات الحالية الـ %d أيضًا' . "\0" . 'تحديث %d منشورًا حاليًا أيضًا' . "\0" . 'تحديث المقال الحالي الـ %d أيضًا','Also update the %d existing term'=>'تحديث المصطلحات الحالية الـ %d أيضًا' . "\0" . 'تحديث الـ %d تصنيفًا الحالية أيضًا' . "\0" . 'تحديث المصطلحين الحاليين الـ %d أيضًا' . "\0" . 'تحديث المصطلحات الحالية الـ %d أيضًا' . "\0" . 'تحديث %d مصطلحًا حاليًا أيضًا' . "\0" . 'تحديث التصنيف الحالي الـ %d أيضًا','Also update the %1$d existing posts and %2$d terms'=>'تحديث %1$d مقالاً حاليًا و %2$d تصنيفًا أيضًا','Also update the %1$d existing post and %2$d terms'=>'تحديث المقال الحالي %1$d و %2$d تصنيفًا أيضًا','Also update the %1$d existing posts and %2$d term'=>'تحديث %1$d مقالاً حاليًا والتصنيف %2$d أيضًا','Also update the %1$d existing post and %2$d term'=>'تحديث المقال الحالي %1$d والتصنيف %2$d أيضًا','This field group is shown on an Options page.'=>'تظهر مجموعة الحقول هذه في صفحة خيارات.','That is usually site-wide content like your header, footer, or global blocks.'=>'عادةً ما يكون ذلك محتوى على مستوى الموقع مثل الترويسة أو التذييل أو المكونات العامة.','To translate that content, use the %1$sWPML Translation Dashboard%2$s.'=>'لترجمة هذا المحتوى، استخدم %1$sلوحة إدارة ترجمة WPML%2$s.','The options below still decide how each field behaves: translated, copied to every language, or kept separately per language.'=>'لا تزال الخيارات أدناه تحدد كيفية سلوك كل حقل: مترجم، أو منسوخ إلى كل لغة، أو محفوظ بشكل منفصل لكل لغة.','This field group also appears on an Options page.'=>'تظهر مجموعة الحقول هذه أيضًا في صفحة خيارات.','That content is translated in the %1$sWPML Translation Dashboard%2$s, and the option you choose here decides how each of its fields behaves.'=>'يتم ترجمة هذا المحتوى في %1$sلوحة إدارة ترجمة WPML%2$s، والخيار الذي تختاره هنا يحدد كيفية سلوك كل حقل من حقوله.','Post Type Translation'=>'ترجمة أنواع المقالات','Labels Translation'=>'ترجمة التسميات','Taxonomy Translation'=>'ترجمة التصنيفات','Finish the ACF <b>Multilingual Setup</b>'=>'أكمل <b>إعداد متعدد اللغات</b> لـ ACF','Before you can start translating, you need to edit each ACF Field Group to set a translation option for the fields inside it.'=>'قبل أن تتمكن من بدء الترجمة، تحتاج إلى تحرير كل مجموعة حقول ACF لتعيين خيار ترجمة للحقول الموجودة بداخلها.','Read more about %1$show to translate your ACF custom fields%2$s'=>'اقرأ المزيد حول %1$sكيفية ترجمة حقول ACF المخصصة%2$s','%1$sSet translation options%2$s'=>'%1$sتعيين خيارات الترجمة%2$s','Let\'s Start Translating!'=>'لنبدأ الترجمة!','Edit each Field Group to select a translation option for the fields inside it. If you don\'t set a translation option, you will not be able to translate your fields.'=>'قم بتحرير كل مجموعة حقول لتحديد خيار ترجمة للحقول الموجودة بداخلها. إذا لم تقم بتعيين خيار ترجمة، فلن تتمكن من ترجمة حقولك.','A field in "%s" has the same name as a field in another field group. WPML stores translation preferences by field name, so two fields that share a name cannot be set differently.'=>'يوجد حقل في ”%s“ له نفس اسم حقل في مجموعة حقول أخرى. يقوم WPML بتخزين تفضيلات الترجمة حسب اسم الحقل، لذا لا يمكن تعيين حقلين يشتركان في الاسم بشكل مختلف.','Some fields in "%s" have the same name as fields in other field groups. WPML stores translation preferences by field name, so fields that share a name cannot be set differently.'=>'بعض الحقول في ”%s“ لها نفس أسماء حقول في مجموعات حقول أخرى. يقوم WPML بتخزين تفضيلات الترجمة حسب اسم الحقل، لذا لا يمكن تعيين الحقول التي تشترك في الاسم بشكل مختلف.','What you set here may not be what your visitors get'=>'ما تعينه هنا قد لا يكون ما يحصل عليه زوارك','The field %1$s also exists in "%2$s". Rename this field to give it a translation setting of its own.'=>'الحقل %1$s موجود أيضًا في ”%2$s“. قم بتغيير اسم هذا الحقل لمنحه إعداد ترجمة خاصًا به.','See both fields'=>'عرض كلا الحقلين','Go to Media Translation settings'=>'انتقل إلى إعدادات ترجمة الوسائط','This content has ACF image, gallery, or file fields, but the alt text, caption, and title of their media will not be sent for translation. To include them, turn on "Translate Media Library texts when translating content" in WPML Media Translation settings.'=>'يحتوي هذا المحتوى على حقول صور أو معرض صور أو ملفات من ACF، ولكن لن يتم إرسال النص البديل والتعليق التوضيحي وعنوان الوسائط الخاصة بها للترجمة. لتضمينها، قم بتشغيل ”ترجمة نصوص مكتبة الوسائط عند ترجمة المحتوى“ في إعدادات WPML Media Translation.','Media texts are not being translated'=>'نصوص الوسائط لا يتم ترجمتها','%1$sGo to Media Translation settings%2$s'=>'%1$sانتقل إلى إعدادات ترجمة الوسائط%2$s','Translate this Options page from the <b>Translation Dashboard</b>'=>'ترجمة صفحة الخيارات هذه من <b>لوحة إدارة الترجمة</b>','You no longer need to switch the admin language to translate options manually. Translate all your options from the %1$sTranslation Dashboard%2$s.'=>'لم تعد بحاجة إلى تبديل لغة المسؤول لترجمة الخيارات يدويًا. ترجم جميع خياراتك من %1$sلوحة إدارة الترجمة%2$s.','Go to the Translation Dashboard'=>'انتقل إلى لوحة إدارة الترجمة','To change a finished translation, go to %1$sTranslation Jobs%2$s and click on the Edit Translation icon.'=>'لتغيير ترجمة مكتملة، انتقل إلى %1$sوظائف الترجمة%2$s وانقر على أيقونة تعديل الترجمة.','Go to Translation Jobs'=>'انتقل إلى وظائف الترجمة','WPML blocked this save to prevent data loss. The form sent about %1$s fields, but the PHP max_input_vars limit on this server (%2$s) let fewer through. Saving now would permanently delete the fields that did not arrive, including repeater rows. Nothing was saved. Ask your host to raise max_input_vars above %1$s and save again.'=>'قام WPML بحظر هذا الحفظ لمنع فقدان البيانات. أرسل النموذج حوالي %1$s حقلاً، لكن حد max_input_vars في PHP على هذا الخادم سمح بمرور (%2$s) فقط. الحفظ الآن سيؤدي إلى حذف الحقول التي لم تصل بشكل دائم، بما في ذلك صفوف حقول التكرار. لم يتم حفظ أي شيء. اطلب من المستضيف رفع max_input_vars إلى أكثر من %1$s واحفظ مرة أخرى.','Save blocked to prevent data loss'=>'تم حظر الحفظ لمنع فقدان البيانات','You need to %1$stranslate this post manually%2$s because the field groups attached to it use different translation options:'=>'تحتاج إلى %1$sترجمة هذا المقال يدويًا%2$s لأن مجموعات الحقول المرفقة به تستخدم خيارات ترجمة مختلفة:','and %d more.'=>'و %d إضافية.','Show all field groups'=>'إظهار كافة مجموعات الحقول','and %d more'=>'و %d إضافية','You need to translate this post manually because the field groups attached to it use different translation options: %s.'=>'تحتاج إلى ترجمة هذا المقال يدويًا لأن مجموعات الحقول المرفقة به تستخدم خيارات ترجمة مختلفة: %s.','Edit %s'=>'تعديل %s','Go to documentation'=>'انتقل إلى الوثائق','This field value is copied from the default language and will be kept in sync across languages.'=>'يتم نسخ قيمة هذا الحقل من اللغة الافتراضية وسيتم الحفاظ على مزامنتها عبر اللغات.','Synchronise translations'=>'مزامنة الترجمات','Keep repeater and flexible sub-fields in the same order as the default language.'=>'الحفاظ على الحقول الفرعية لحقول التكرار والمحتوى المرن بنفس ترتيب اللغة الافتراضية.','ACFML Synchronise translations'=>'مزامنة ترجمات ACFML','Translate ACF Local JSON and PHP-Registered Fields'=>'ترجمة حقول ACF المسجلة عبر PHP و Local JSON','ACF allows you to %1$sregister fields via PHP%2$s or %3$ssave field settings as JSON files%4$s. You can also save post types, taxonomies, or options pages settings to JSON files.'=>'يتيح لك ACF %1$sتسجيل الحقول عبر PHP%2$s أو %3$sحفظ إعدادات الحقول كملفات JSON%4$s. يمكنك أيضًا حفظ إعدادات أنواع المقالات أو التصنيفات أو صفحات الخيارات في ملفات JSON.','Configure how ACF Multilingual handles translations for these items.'=>'تكوين كيفية تعامل ACF Multilingual مع الترجمات لهذه العناصر.','Sync <b>Translation Preferences</b> for Local Fields'=>'مزامنة <b>تفضيلات الترجمة</b> للحقول المحلية','Don’t sync translation preferences'=>'عدم مزامنة تفضيلات الترجمة','Sync once now'=>'مزامنة مرة واحدة الآن','Sync on every request (may affect performance)'=>'المزامنة عند كل طلب (قد يؤثر على الأداء)','Register Labels for Translation'=>'تسجيل التسميات للترجمة','Scans post types, taxonomies, options pages, and field groups stored in the "acf-json" directory, then registers their labels with WPML so you can translate them.'=>'يفحص أنواع المقالات والتصنيفات وصفحات الخيارات ومجموعات الحقول المخزنة في دليل ”acf-json“، ثم يسجل تسمياتها مع WPML حتى تتمكن من ترجمتها.','Don’t register labels'=>'عدم تسجيل التسميات','Register labels now'=>'تسجيل التسميات الآن','Apply'=>'طبِّق','The synchronization of translation preferences is disabled.'=>'تم تعطيل مزامنة تفضيلات الترجمة.','Translation preferences synchronized.'=>'تمت مزامنة تفضيلات الترجمة.','The synchronization of translation preferences is enabled.'=>'تم تمكين مزامنة تفضيلات الترجمة.','%s group'=>'%s مجموعات' . "\0" . '%s مجموعة' . "\0" . 'مجموعتان اثنتان %s' . "\0" . '%s مجموعات' . "\0" . '%s مجموعة' . "\0" . 'مجموعة %s واحدة','%s post type'=>'%s أنواع منشورات' . "\0" . '%s من أنواع المقالات' . "\0" . '%s من أنواع المقالات' . "\0" . '%s أنواع منشورات' . "\0" . '%s نوع منشور' . "\0" . 'نوع مقال %s واحد','%s taxonomy'=>'%s تصنيفات' . "\0" . '%s تصنيفًا' . "\0" . 'تصنيفان اثنان %s' . "\0" . '%s تصنيفات' . "\0" . '%s تصنيفًا' . "\0" . 'تصنيف %s واحد','%s options page'=>'%s صفحات خيارات' . "\0" . '%s من صفحات الخيارات' . "\0" . 'صفحتا خيارات اثنتان %s' . "\0" . '%s صفحات خيارات' . "\0" . '%s صفحة خيارات' . "\0" . 'صفحة خيارات %s واحدة','No local field groups, post types, taxonomies, or Options pages were found.'=>'لم يتم العثور على مجموعات حقول محلية أو أنواع مقالات أو تصنيفات أو صفحات خيارات.','Used between elements of a two elements list and '=>' و ','Used before the last element of a three or more elements list, and '=>'، و ','Successfully registered labels for %s.'=>'تم تسجيل تسميات %s بنجاح.','%1$sChange translation settings%2$s'=>'%1$sتغيير إعدادات الترجمة%2$s','%1$sTranslate labels%2$s'=>'%1$sترجمة التسميات%2$s','Not translatable'=>'غير قابل للترجمة','Translatable'=>'قابل للترجمة','only show translated items'=>'إظهار العناصر المترجمة فقط','use translation if available or fallback to default language'=>'استخدام الترجمة إذا كانت متوفرة أو العودة إلى اللغة الافتراضية','This content must be translated manually due to the translation option you selected for the "%1$s" field group.'=>'يجب ترجمة هذا المحتوى يدويًا بسبب خيار الترجمة الذي حددته لمجموعة الحقول ”%1$s“.']];